UPDATE public.weekly_question_pool SET prompt='What is a surprisingly bold but kind choice you made while traveling?' WHERE id=34; UPDATE public.game_cards SET prompt='Who is most likely to learn a new dance step and teach the squad?' WHERE id=156 AND trip_id IS NULL; UPDATE public.at_home_pack_items SET body='Which public transport in Thailand would you like to learn more about: tuk-tuk, longtail boat or train?' WHERE id=55; UPDATE public.at_home_pack_items SET body='What animal would you like to learn more about in Thailand: elephant, tiger or gecko?' WHERE id=61; UPDATE public.at_home_pack_items SET title='Pattern sketch',body='Sketch a festival-inspired pattern after researching its meaning from a reliable source.' WHERE id=68; INSERT INTO public.content_variants(kind,text,trip_id) SELECT 'bingo',v,NULL FROM (VALUES('Take a water break with your squad'),('Stretch gently together after a long ride'),('Spot a shaded public place to rest for five minutes'),('Share one sleep tip that helps you feel rested on a trip')) AS s(v) WHERE false;